class Solution {
    struct BIT {
        vector<int> bit;
        BIT(int n) : bit(n + 1, 0) {}
        void add(int i, int delta) {
            for (; i < (int)bit.size(); i += i & -i) bit[i] += delta;
        }
        int sum(int i) {
            int ans = 0;
            for (; i > 0; i -= i & -i) ans += bit[i];
            return ans;
        }
    };
public:
    long long minInversionCount(vector<int>& nums, int k) {
        vector<int> vals = nums;
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        BIT bit(vals.size());
        long long inv = 0, answer = LLONG_MAX;
        for (int i = 0; i < (int)nums.size(); ++i) {
            int x = lower_bound(vals.begin(), vals.end(), nums[i]) - vals.begin() + 1;
            int len = min(i, k - 1);
            inv += len - bit.sum(x);
            bit.add(x, 1);
            if (i >= k - 1) {
                answer = min(answer, inv);
                int old = lower_bound(vals.begin(), vals.end(), nums[i - k + 1]) - vals.begin() + 1;
                bit.add(old, -1);
                inv -= bit.sum(old - 1);
            }
        }
        return answer;
    }
};
